-- GENERATED by `wfj generate` from data/quest/quest-0006.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [6001] = { "Corpo e cuore", "Usa la ⟦Cenarion Moondust=Polvere di Luna Cenariana⟧ sulla Moonkin Stone di Auberdine per far comparire Lunaclaw. A quel punto dovrai affrontare Lunaclaw e conquistare la forza del corpo e del cuore che possiede.\n\nQuando hai finito, parla con Mathrengyl Bearwalker a Darnassus.", "Subito a est di Auberdine si trovano molte grotte dei lunagufi. Quella più vicina ad Auberdine custodisce una Moonkin Stone. Lunaclaw, il difensore della pietra, ti affronterà solo quando vi verrà applicata della ⟦Cenarion Moondust=Polvere di Luna Cenariana⟧. Lunaclaw racchiude in sé una forza che tu, come membro dell'Artiglio, devi usare.\n\nTi sei guadagnat<o/a> il diritto di usare questa ⟦Cenarion Moondust=Polvere di Luna Cenariana⟧, {name}... ora dimostrami di esserti guadagnat<o/a> il diritto di possedere la forza del corpo e la forza del cuore necessarie a un druido!", "Quando avrai affrontato la prova che ti attende, la tua comprensione della forza del corpo e della forza del cuore sarà completa. Fino ad allora, non posso aiutarti oltre.", "Hai finalmente compiuto il tuo grande passo in un mondo molto più vasto, {name}. Sento in te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che possedeva Lunaclaw.\n\nNon ci sono più ostacoli sul tuo cammino... lascia che ora ti insegni cosa significa essere <un/una> <Druido/Druida> dell'Artiglio!", 0x9109866f, 0xe7d92ce2, 0xd25471ff, 0xf431a09c, 0x5233b46d, "....." },
  [6002] = { "Corpo e cuore", "Usa la ⟦Cenarion Lunardust=Polvere Lunare Cenariana⟧ sulla Moonkin Stone tra Mulgore e le ⟦Barrens=Savane⟧ per far comparire Lunaclaw. A quel punto dovrai affrontare Lunaclaw e conquistare la forza del corpo e del cuore che possiede.\n\nQuando hai finito, parla con Turak Runetotem a ⟦Thunder Bluff=Picco del Tuono⟧.", "Nelle terre a ovest di Taurajo, nelle ⟦Barrens=Savane⟧, appena prima che lascino il posto a Mulgore, si trova una Moonkin Stone. I lunagufi sono bestie speciali, non originarie di queste parti. Lunaclaw, il difensore della pietra, ti affronterà quando vi verrà applicata della ⟦Cenarion Lunardust=Polvere Lunare Cenariana⟧. Lunaclaw racchiude in sé una forza che tu, come membro dell'Artiglio, devi usare.\n\nTi sei guadagnat<o/a> il diritto di usare questa ⟦Cenarion Lunardust=Polvere Lunare Cenariana⟧, {name}... ora dimostrami di esserti guadagnat<o/a> il diritto di possedere la forza del corpo e la forza del cuore necessarie a un druido!", "Quando avrai affrontato la prova che ti attende, la tua comprensione della forza del corpo e della forza del cuore sarà completa. Fino ad allora, non posso aiutarti oltre.", "Hai finalmente compiuto il tuo grande passo in un mondo molto più vasto, {name}. Sento in te l'insegnamento del Great Bear Spirit, e sento che hai ricevuto la forza che possedeva Lunaclaw.\n\nNon ci sono più ostacoli sul tuo cammino... lascia che ora ti insegni cosa significa essere <un/una> <Druido/Druida> dell'Artiglio!", 0x9109866f, 0xd7388bf3, 0x130e04b9, 0xf431a09c, 0x5233b46d, "....." },
  [6061] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per domare un Adult Plainstrider. Metti alla prova le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Yaw Sharpmane nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Per un tauren è importante seguire le tradizioni dei nostri antenati combattendo creature possenti. Sconfiggendo queste creature possiamo accoglierne gli spiriti, e questo ci avvicina alla Madre Terra.\n\nAllo stesso modo, addomesticare una bestia che combatta al nostro fianco ci aiuta a diventare un tutt'uno con la natura che ci circonda. Col tempo imparerai ad addomesticare una bestia a tua scelta. Ma tutto richiede pratica, e hai molto da imparare. Comincia prendendo questo Bastone per Addomesticare: devi addomesticare un Adult Plainstrider.", "Metti alla prova le tue abilità, {name}. Addomestica l'Adult Plainstrider.", "La Madre Terra mi ha mandato dei segni: hai fatto un buon lavoro.", 0xecd97a9a, 0x7e3b8d01, 0x02e5038d, 0xaa8943a4, 0xe57154b4, "....." },
  [6062] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per domare un Dire Mottled Boar. Metti alla prova le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Saper imporre la propria autorità sulla natura è un'abilità ammirevole. Come <cacciatore/cacciatrice>, devi sforzarti di imparare a usare la forza e il potere insiti in qualsiasi creatura tu scelga.\n\nOttenere il controllo di un animale non è un'impresa facile; è un compito da affrontare con grande determinazione.\n\nCome primo incarico, prendi questo Bastone per Addomesticare e usalo per addomesticare un Dire Mottled Boar. Ne troverai parecchi vicino a ⟦Razor Hill=Tranciacolle⟧. Metti alla prova le tue abilità in battaglia con il cinghiale al tuo fianco, poi torna da me.", "Buona fortuna, giovane <cacciatore/cacciatrice>.", "Hai fatto un buon lavoro, {name}. Credo che tu sia <pronto/pronta> per il prossimo compito.", 0xecd97a9a, 0xbdba9086, 0x62c476e9, 0xd07d6bc7, 0xac1c2d65, "....." },
  [6063] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per domare un Webwood Lurker. Metti alla prova le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Dazalar a Dolanaar.", "Come <cacciatore/cacciatrice>, è importante ricordare la responsabilità che tieni tra le mani. La natura non è un potere che si possa piegare ai nostri desideri; va rispettata e riconosciuta come qualcosa di più forte della tua stessa esistenza.\n\n{name}, devi dimostrare di averlo compreso prima di ottenere la capacità di addomesticare un animale come tuo compagno.\n\nIl tuo primo compito è prendere questo Bastone per Addomesticare. Con esso potrai addomesticare un Webwood Lurker. Addomesticalo e metti alla prova le tue abilità di <cacciatore/cacciatrice>.", "Imparerai, {name}, e un giorno sarai <un/una> grande <cacciatore/cacciatrice>.", "Eccellente, {name}! Impari davvero in fretta.", 0xecd97a9a, 0x72db5042, 0x39ad25e9, 0x407acae4, 0x7f1a8496, "....." },
  [6064] = { "Addomesticare la bestia", "Usa il ⟦Taming Rod=Bastone per Addomesticare⟧ per domare un Large Crag Boar. Metti alla prova le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Grif Wildheart a Kharanos.", "Salve, <ragazzo/ragazza>! Allora, vorresti sapere come avere un famiglio tutto tuo?\n\nBe', cominciamo. Non c'è niente di più importante dell'equipaggiamento quando si va a caccia, ma del mio nuovo ⟦Shrapnel Blaster=Fulminatore a Schegge⟧ possiamo parlare un'altra volta. Per ora concentriamoci su qualcosa che di sicuro t'interessa parecchio: un famiglio!\n\nIl modo migliore per imparare è provare diverse creature come compagni e vedere cosa ti piace. Quindi trova un Large Crag Boar e usa il Bastone per Addomesticare per domarlo.", "Non preoccuparti, <ragazzo/ragazza>! Potrai provarne qualcuno prima di doverne scegliere uno solo.", "Lo so, lo so: ti stai chiedendo cosa viene dopo, eh?!", 0xecd97a9a, 0x19250c04, 0x4bb3619f, 0x2a062314, 0x7fe27a35, ".....", nil, nil, 0x1065c71d, nil, nil },
  [6065] = { "La via del cacciatore", "Parla con Yaw Sharpmane nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Yaw Sharpmane al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che tu sia <pronto/pronta>...", 0xe59cef47, 0x44416cc1, 0xcdcddc29, nil, 0x97654cb4, "...m." },
  [6066] = { "La via del cacciatore", "Parla con Yaw Sharpmane nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Yaw Sharpmane al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che tu sia <pronto/pronta>...", 0xe59cef47, 0x44416cc1, 0xcdcddc29, nil, 0x97654cb4, "...m." },
  [6067] = { "La via del cacciatore", "Parla con Yaw Sharpmane nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Yaw Sharpmane al ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che tu sia <pronto/pronta>...", 0xe59cef47, 0x44416cc1, 0xcdcddc29, nil, 0x97654cb4, "...m." },
  [6068] = { "La via del cacciatore", "Parla con Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Thotar a ⟦Razor Hill=Tranciacolle⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è ora che tu cominci il tuo addestramento.", 0xe59cef47, 0xccc0cc0b, 0xa19701ce, nil, 0x2462bb57, "...m." },
  [6069] = { "La via del cacciatore", "Parla con Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Thotar a ⟦Razor Hill=Tranciacolle⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo che tu sia <pronto/pronta> per essere <addestrato/addestrata>...", 0xe59cef47, 0xccc0cc0b, 0xa19701ce, nil, 0x136d5bec, "...m." },
  [6070] = { "La via del cacciatore", "Parla con Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Thotar a ⟦Razor Hill=Tranciacolle⟧. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è ora che tu cominci il tuo addestramento.", 0xe59cef47, 0xccc0cc0b, 0xa19701ce, nil, 0x2462bb57, "...m." },
  [6071] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6072] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo che sia il momento...", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0x467a6a72, "...m." },
  [6073] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6074] = { "La via del cacciatore", "Parla con Grif Wildheart a Kharanos.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Grif Wildheart a Kharanos. Può metterti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che anche tu sia pront<o/a>...", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6075] = { "La via del cacciatore", "Parla con Grif Wildheart a Kharanos.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Grif Wildheart a Kharanos. Può metterti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che anche tu sia pront<o/a>...", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6076] = { "La via del cacciatore", "Parla con Grif Wildheart a Kharanos.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Grif Wildheart a Kharanos. Può metterti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, credo proprio che anche tu sia pront<o/a>...", 0xe59cef47, 0x7378e497, 0x892ec4fe, nil, 0xc84c7dad, "...m." },
  [6081] = { "Addestrare la bestia", "Parla con Ormak Grimshot a Orgrimmar.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le abilità per addestrarlo.\n\nRecati a Orgrimmar. Lì dovrai parlare con uno dei nostri cacciatori più venerati, Ormak Grimshot. Ti darà la capacità di addestrare il tuo nuovo famiglio. Lo troverai vicino alla Hall of the Brave.\n\nBuona fortuna, {name}.", nil, "Vedo che sei <un/una> giovane <cacciatore/cacciatrice>. Sì, ti concederò le abilità necessarie per addestrare e guidare il tuo famiglio. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nOra va', <cacciatore/cacciatrice>. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0x2fb3c65d, 0x4f2112ec, nil, 0x455cd3ee, "...m." },
  [6082] = { "Addomesticare la bestia", "Addomestica uno ⟦Scorpid=Scorpide⟧, l'Armored Scorpid, con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi torna da Thotar a ⟦Razor Hill=Tranciacolle⟧.", "L'ultima creatura che devi addomesticare è una che dovresti sforzarti di emulare: l'Armored Scorpid. Colpisce in modo rapido e sicuro; controllare una forza come questa è il tuo destino di <cacciatore/cacciatrice>.\n\nAl tuo ritorno ti conferirò le abilità necessarie per addomesticare un animale a tua scelta; quella creatura sarà ai tuoi ordini. Sotto il tuo controllo, il famiglio acquisirà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo a tuo piacimento.", "Sei riuscit<o/a> ad addomesticare lo scorpide?", "Hai imparato tutto ciò che posso insegnarti, {name}. È tempo che tu metta a frutto ciò che hai imparato qui e scelga un famiglio tutto tuo.\n\nEcco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio: te le sei guadagnate.", 0xecd97a9a, 0x2768b0fc, 0x861877c1, 0x5354bf2d, 0xf50c040e, "....." },
  [6083] = { "Addomesticare la bestia", "Addomestica un Surf Crawler con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Thotar a ⟦Razor Hill=Tranciacolle⟧.", "Il vantaggio che un famiglio ti offre contro i tuoi rivali è ben noto, {name}. Quando ottieni il controllo su un'altra creatura, aggiungi forza alla tua. Il tuo famiglio deve diventare un'estensione di te stess<o/a>.\n\nIl prossimo compito ti chiede di lasciare la terraferma: troverai la prossima creatura nelle acque al largo della costa. Di fronte al ⟦Sen'jin Village=Villaggio di Sen'jin⟧, vicino alle ⟦Echo Isles=Isole dell'Eco⟧, cerca un granchio vivace chiamato Surf Crawler. Usa il Bastone per Addomesticare per domarlo, poi metti in pratica le tue abilità.", "Devi fare pratica per acquisire le abilità necessarie a controllare bene il tuo famiglio. Hai addomesticato un Surf Crawler?", "Impari in fretta, {name}. Hai fatto un buon lavoro.", 0xecd97a9a, 0x79ae328f, 0x2fe7f794, 0x317634b5, 0x65d417ae, "....." },
  [6084] = { "Addomesticare la bestia", "Addomestica uno Snow Leopard con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi torna da Grif Wildheart a Kharanos.", "Quei Crag Boar son belli robusti; magari vorresti qualcosa con un po' più di finezza? Va bene, allora, ho proprio quel che fa per te. A sud-est di qui troverai dei grossi felini bianchi chiamati Snow Leopard. Proprio come un fucile intagliato con eleganza, dietro il loro bell'aspetto si nasconde un combattente potente, capace di fare danni enormi. Vedrai che sono molto più agili e svelti del cinghiale che hai addomesticato.\n\nPrendi questo Bastone per Addomesticare e vedi come ti trovi con lo Snow Leopard.", "Che ne pensi dello Snow Leopard, {name}?", "Quando sentirò che hai imparato abbastanza, ti concederò la capacità di scegliere qualsiasi famiglio tu preferisca.", 0xecd97a9a, 0x71c04a53, 0x18410c9d, 0x00a7c273, 0xa900ecfd, "....." },
  [6085] = { "Addomesticare la bestia", "Addomestica un Ice Claw Bear con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Grif Wildheart a Kharanos.", "Forse ti piacerebbe una creatura che ha poco più della forza bruta. L'Ice Claw Bear è un compagno eccellente per chi è alle prime armi come te, e lo trovi a est di Kharanos. Ecco il Bastone per Addomesticare; prova questo animale come famiglio e vedi se ti piace!\n\nQuando torni, ti darò le abilità che ti servono per addomesticare un animale a tua scelta; quella creatura affronterà le sfide che affronti tu e acquisirà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo come ti pare.", "Hai già addomesticato l'Ice Claw Bear?", "Ecco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come ti pare.\n\nTrovati un famiglio buono e leale, e goditi la caccia!", 0xecd97a9a, 0xe2aae2d4, 0x732759ee, 0x687f27e9, 0x427d0b77, "....." },
  [6086] = { "Addestrare la bestia", "Parla con Belia Thundergranite a ⟦Ironforge=Forgiardente⟧.", "{name}, ora hai il potere di addomesticare un famiglio, ma devi anche imparare ad addestrarlo.\n\nVa' a ⟦Ironforge=Forgiardente⟧ e cerca la Hall of Arms. Lì devi parlare con una delle nostre addestratrici di animali più stimate, Belia Thundergranite. Ti darà il potere di addestrare il tuo nuovo famiglio, quindi muoviti, <ragazzo/ragazza>!\n\nBelia è una tipa alla mano; non avrai problemi a guadagnarti la sua approvazione. Buona fortuna, {name}.", nil, "Una nuova recluta, eh? Vedo che sei sulla buona strada per diventare <un/una> grande {class}.\n\nSì, posso conferirti le abilità necessarie per addestrare e guidare il tuo famiglio. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda che il segreto per ottenere il massimo dal tuo nuovo famiglio è rispettarlo e trattarlo bene. In cambio, il tuo famiglio sarà il tuo amico più leale.", 0xdbeedc0e, 0x4c05bef3, 0x77988ad7, nil, 0x760bb7bd, "...m.", nil, nil, 0xf137678c, nil, nil },
  [6087] = { "Addomesticare la bestia", "Addomestica un Prairie Stalker con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Yaw Sharpmane nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "Hai uno spirito ardente, <cacciatore/cacciatrice>, sempre pronto alla prossima sfida.\n\nIl tuo prossimo compito è conquistare la compagnia di un lupo noto come Prairie Stalker. Questa creatura è rapida e impavida; prendendo questa bestia come famiglio, dovrai fare tue anche queste qualità.\n\nIn battaglia imparerai come tu e il tuo famiglio diventerete una squadra. Alla fine dovrete agire come uno solo, muscolo con muscolo.\n\nEcco il Bastone per Addomesticare, {name}. Addomestica un Prairie Stalker e metti in pratica le tue abilità.", "Hai trovato un Prairie Stalker?", "Sì... La Madre Terra ritiene che tu sia pront<o/a> per la prossima lezione.", 0xecd97a9a, 0x4c6a673d, 0xcbcfeb92, 0xf06164c3, 0x0370a830, "....." },
  [6088] = { "Addomesticare la bestia", "Addomestica uno Swoop con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Yaw Sharpmane nel ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "L'ultimo compito che ho per te richiede di addomesticare una creatura che abita il cielo. Lo Swoop è un avversario difficile, ma come alleato ti darà i suoi attacchi affilati e la sua presenza minacciosa.\n\nPer volere della Madre Terra, al tuo ritorno ti conferirò le abilità necessarie per addomesticare un animale a tua scelta come compagno; questa creatura affronterà le sfide che affronti tu e acquisirà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo a tuo piacimento.", "Presto sarai pront<o/a>, {name}.", "Hai imparato tutto ciò che posso insegnarti, {name}. Che le benedizioni della Madre Terra ti guidino nella scelta di un famiglio.\n\nEcco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio e onora la Madre Terra.", 0xecd97a9a, 0x64c2eb6a, 0x3d7058f9, 0x3bda1794, 0x834b33ff, "....." },
  [6089] = { "Addestrare la bestia", "Parla con Holt Thunderhorn sull'⟦Hunter Rise=Altura dei Cacciatori⟧ a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le abilità per addestrarlo.\n\nRecati a ⟦Thunder Bluff=Picco del Tuono⟧. Lì dovrai parlare con uno dei nostri cacciatori più venerati, Holt Thunderhorn. Se ti riterrà degn<o/a>, ti darà la capacità di addestrare il tuo nuovo famiglio.\n\nHolt ha sconfitto le bestie più potenti e temute di Azeroth, e comanda molte creature possenti. Il suo legame con la Madre Terra è forte, e puoi imparare molto da lui. Buona fortuna, {name}.", nil, "Vedo che sei <un/una> giovane {class}. Sì, posso conferirti le abilità necessarie per addestrare e guidare il tuo famiglio. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nOra va'. Che la Madre Terra ti guidi sul tuo cammino. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0x9f1dae7e, 0xc78eab1d, nil, 0x104e785e, "...m." },
  [6101] = { "Addomesticare la bestia", "Addomestica un Nightsaber Stalker con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Dazalar a Dolanaar.", "La varietà della natura è qualcosa su cui si può contare, {name}. È prevedibile nel senso che non resta mai uguale: cambia sempre.\n\nI compiti che ti affiderò ti aiuteranno a vedere e apprezzare le enormi differenze tra le creature che potresti scegliere come compagne.\n\nPrendi questo Bastone per Addomesticare e usalo per addomesticare un Nightsaber Stalker, che trovi a sud. Metti in pratica le tue abilità di <cacciatore/cacciatrice>. Allora inizierai a comprendere le somiglianze e le differenze della natura.", "Comprendere l'equilibrio tra la natura e se stessi è uno stile di vita per ogni Elfo della Notte.", "Vedo il tuo impegno, e vedo che hai compreso ciò che ti ho insegnato, {name}.", 0xecd97a9a, 0xd54ea322, 0x4cf39634, 0x2bb052d9, 0xe3639023, "....." },
  [6102] = { "Addomesticare la bestia", "Addomestica uno Strigid Screecher con il ⟦Taming Rod=Bastone per Addomesticare⟧. Metti in pratica le tue abilità, poi riporta il ⟦Taming Rod=Bastone per Addomesticare⟧ a Dazalar a Dolanaar.", "Hai addomesticato due creature che abitano la terra; ora devi addomesticarne una che solca i cieli. Usa il Bastone per Addomesticare per domare uno Strigid Screecher, che trovi a ovest di qui. Metti in pratica le tue abilità con questo possente gufo al tuo fianco.\n\nAl tuo ritorno ti conferirò le abilità necessarie per addomesticare un animale a tua scelta come compagno; questa creatura affronterà le sfide che affronti tu e acquisirà esperienza insieme a te. Ti mostrerò anche come richiamarlo e congedarlo a tuo piacimento.", "Sono fiero dei tuoi successi, {name}. Hai portato a termine l'ultimo compito che ti ho affidato?", "Hai imparato tutto ciò che posso insegnarti, {name}. Permettimi di darti un ultimo consiglio: scegli con giudizio il tuo primo famiglio. Sceglierai una creatura della terra, dell'acqua o del cielo? Qualunque sia, senza dubbio il tuo famiglio starà con te per molto tempo.\n\nEcco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio: te le sei guadagnate.", 0xecd97a9a, 0xe53bb451, 0x3445b668, 0xc9470946, 0xdeb475c1, "....." },
  [6103] = { "Addestrare la bestia", "Parla con Jocaste nell'⟦Cenarion Enclave=Enclave Cenariana⟧, a Darnassus.", "Ora hai il potere di addomesticare un famiglio, ma devi anche acquisire le abilità per addestrarlo.\n\nRecati a Darnassus. Lì dovrai parlare con una delle nostre cacciatrici più venerate, Jocaste. Ti darà la capacità di addestrare il tuo nuovo famiglio, quindi affrettati.\n\nAnche se Jocaste può sembrare severa, è sempre lieta di vedere un altro cacciatore salire di grado. Trattala con rispetto e lei farà altrettanto. Buona fortuna, {name}.", nil, "Vedo che sei <un/una> <cacciatore/cacciatrice> alle prime armi. Sì, posso conferirti le abilità necessarie per addestrare e guidare il tuo famiglio. Non solo potrai insegnargli nuove abilità, ma ora potrai anche nutrirlo e rianimarlo, se dovesse cadere in battaglia.\n\nRicorda, {name}, rispetta sempre l'equilibrio e guarda con meraviglia la natura che ti circonda. Ora va'. Ci parleremo di nuovo più avanti.", 0xdbeedc0e, 0x6e901431, 0x3d135ae6, nil, 0xce7253c1, "...m." },
  [6121] = { "Nuove lezioni", "Va' a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Ora sei pront<o/a> a conoscere i veleni e il potere che noi druidi abbiamo su di essi, {name}. Cenarius ci ha concesso la capacità di purificare anche i veleni più immondi con un semplice incantesimo. Questo dono non va preso alla leggera... e per assicurarmi che tu impari la lezione, lavorerai per contrastare gli effetti degli avvelenamenti come farebbe un profano.\n\nVa' a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze; attende il tuo arrivo per cominciare la lezione.", nil, "Salute, giovane druid<o/a>, sono lieto di vederti pront<o/a> e desideros<o/a> di imparare a curare i veleni.\n\nMentre in passato la maggior parte dei druidi veniva sottoposta a prove prestabilite, il tuo lavoro non avrà niente del genere. Ad Auberdine c'è stata un'ondata di avvelenamenti tra gli animali, e il villaggio non è riuscito a curarli. Per questo un loro rappresentante ha chiesto aiuto a ⟦Moonglade=Radaluna⟧, e noi ti mandiamo laggiù ad aiutarli. Non è un'esercitazione: il lavoro che farai è del tutto reale. Tienilo a mente.", 0xe3814355, 0xb25e3d68, 0x738324f8, nil, 0xe3b1d128, "...m." },
  [6122] = { "La fonte principale", "Usa il ⟦Empty Cliffspring Falls Sampler=Campione delle Cascate di Altafonte Vuoto⟧ per prelevare un campione d'acqua all'imbocco della grotta vicino alle cascate.\n\nConsegna il ⟦Filled Cliffspring Falls Sampler=Campione delle Cascate di Altafonte Pieno⟧ ad Alanndarian Nightsong, ad Auberdine, a ⟦Darkshore=Rivafosca⟧.", "Le ⟦Cliffspring Falls=Cascate di Altafonte⟧, a ⟦Darkshore=Rivafosca⟧, sono la fonte principale di acqua potabile della regione, e ora sospetto che siano anche la fonte principale del veleno che colpisce la fauna locale, in particolare i cervi. Usa questo campionatore per prelevare un po' d'acqua all'imbocco della grotta; fa' attenzione, perché ora in una grotta vicino alle cascate vivono dei naga pericolosi.\n\nUna volta riempito, consegnalo ad Alanndarian Nightsong, ad Auberdine. È lei che ha chiesto il nostro aiuto, e lavorerai con lei per curare questo male.", "Ti manda il ⟦Cenarion Circle=Circolo Cenariano⟧ di ⟦Moonglade=Radaluna⟧? Magnifico! Qui abbiamo una vera crisi con quei poveri cervi, e siamo felici di ricevere tutto l'aiuto possibile.\n\nHai il campione d'acqua che Dendrite Starblaze ha detto che avresti portato? Mi ha avvisata che ne avresti prelevato uno, così da poter lavorare insieme a una cura...", "Per Elune, quest'acqua è disgustosa! Non c'è da stupirsi che i cervi siano malati.\n\nQualcosa sta inquinando l'acqua e, di conseguenza, corrompe l'intera falda di Rivafosca. Si sono visti cervi malati in tutta la zona, e non solo vicino al fiume. Anche se quest'acqua è con ogni probabilità una delle fonti principali del male che si diffonde, qui c'è all'opera qualcos'altro.\n\nChe tu ci creda o no, quest'acqua ci aiuterà a preparare una cura. Mentre la studio, mi servono alcuni ingredienti per formulare la cura...", 0xfe91905d, 0xed0bc128, 0xe6b38f20, 0x7f300676, 0xc7a9f8eb, "....." },
  [6123] = { "Gli ingredienti della cura", "Porta 5 Earthroot e 12 Lunar Fungus ad Alanndarian Nightsong, ad Auberdine, perché possa preparare un balsamo curativo.", "L'acqua farà da base per il balsamo curativo che preparerò per i cervi. Per le proprietà curative mi serve un po' di Earthroot. Gli erboristi sanno come trovarla, quindi, se siamo sfortunati e tu non lo sei, dovrai trovarne uno che ci aiuti.\n\nInfine, per renderlo efficace, mi serve un po' di Lunar Fungus. Trovarne le fioriture è abbastanza facile: sono dappertutto nelle grotte appena a est di qui. Nelle grotte vivono dei lunagufi, e ultimamente sono irritabili, quindi fa' attenzione.", "Hai i reagenti che mi servono per preparare il balsamo? I cervi non migliorano da soli, quindi è meglio sbrigarsi ad aiutarli!", "Questo va bene, {name}, tanto che dovrebbe bastare a preparare diverse dosi di balsamo, almeno quante ne servono per cominciare a fare la differenza.\n\nPreparare una cura per i veleni a volte può essere molto difficile, perché spesso ognuno richiede un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento senza doverti preoccupare degli ingredienti esatti dell'antidoto!\n\nOra lasciami mettere al lavoro!", 0xc0a4b4dc, 0x14a92d63, 0xd43adcc8, 0xd5399fb4, 0x0d585714, "....." },
  [6124] = { "Curare i malati", "Usa il ⟦Curative Animal Salve=Balsamo Curativo Animale⟧ su 10 Sickly Deer sparsi per ⟦Darkshore=Rivafosca⟧: dovrebbe guarirli. I Sickly Deer sono stati segnalati a partire da sud del ⟦Cliffspring River=Fiume Altafonte⟧, a nord di Auberdine, fino alla parte meridionale di ⟦Darkshore=Rivafosca⟧, dove comincia ⟦Ashenvale=Valtetra⟧.", "Con i reagenti che mi hai portato ho preparato abbastanza balsamo per dieci dosi, {name}. Mentre lavoro con il villaggio per prepararne ancora, vorrei che tu ci aiutassi a portarci avanti. In tutta ⟦Darkshore=Rivafosca⟧ ci sono cervi malati; usa il balsamo su di loro e guariscili dal loro male.\n\nSono sicura che Dendrite Starblaze, a ⟦Moonglade=Radaluna⟧, vorrà parlarti quando avrai finito. Ti prego, porta i ringraziamenti di Auberdine al ⟦Cenarion Circle=Circolo Cenariano⟧ laggiù... e lascia che ti ringrazi io stessa, di persona, per l'aiuto che ci hai dato!", "Hai portato a termine ciò che ti ha chiesto Alanndarian Nightsong di Auberdine? Il tuo lavoro non è completo finché non lo farai.", "Hai fatto bene a curare i cervi malati di ⟦Darkshore=Rivafosca⟧; sono vittime inconsapevoli di una contaminazione e di una corruzione più grandi che si stanno diffondendo in tutta la terra. A Darnassus c'è chi sceglie di riconoscere questa minaccia... e c'è chi ignora i segni sempre più evidenti. Spero che tu non sia tra quelli che chiudono gli occhi davanti ai fatti, {name}.\n\nIn ogni caso, hai dimostrato il tuo valore come amic<o/a> della natura e del Circolo: prendi questo come simbolo.", 0x0116fddd, 0x20fba3fe, 0xbc2e713b, 0xb12ec810, 0x848c8bee, "....." },
  [6125] = { "Potere sul veleno", "Torna da Mathrengyl Bearwalker, nell'⟦Cenarion Enclave=Enclave Cenariana⟧, a Darnassus.", "Hai imparato cosa significa curare un veleno senza il beneficio dell'aiuto spirituale. Ricorda ciò che gli altri devono sopportare nel combattere le afflizioni velenose, ora che stai per abbracciare il tuo nuovo potere sul veleno.\n\nOra dovresti tornare da Mathrengyl Bearwalker, a Darnassus, {name}. Senza dubbio ha un incantesimo molto importante da insegnarti, ora che hai compreso la lezione che ti è stata impartita.\n\nAddio, giovane druid<o/a>. Ci parleremo ancora.", nil, "Bentornat<o/a>. Ho seguito i tuoi progressi in questa lezione da quando sei partit<o/a>, e devo ammettere che mi ha sorpreso sapere della situazione ad Auberdine. La faccenda merita ulteriori indagini, perché l'introduzione di simili veleni nell'ambiente turba profondamente l'equilibrio.\n\nHai mantenuto grazia e sangue freddo sotto pressione. Per questo, non trovo modo migliore per ricompensarti che con un potere permanente sul veleno. Usalo bene, {name}... usalo bene.", 0xfaefb521, 0x6562a80b, 0xe76f8205, nil, 0x02ded2c7, "...m.", nil, nil, 0xe5d51b88, nil, nil },
  [6126] = { "Nuove lezioni", "Va' a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze nel villaggio di ⟦Nighthaven=Nottequieta⟧.", "Ora sei pront<o/a> a conoscere i veleni e il potere che noi druidi abbiamo su di essi, {name}. Cenarius ci ha concesso la capacità di purificare anche i veleni più immondi con un semplice incantesimo. Questo dono non va preso alla leggera... e per assicurarmi che tu impari la lezione, lavorerai per contrastare gli effetti degli avvelenamenti come farebbe un profano.\n\nVa' a ⟦Moonglade=Radaluna⟧ e parla con Dendrite Starblaze; attende il tuo arrivo per cominciare la lezione.", nil, "Salute, giovane druid<o/a>, sono lieto di vederti pront<o/a> e desideros<o/a> di imparare a curare i veleni.\n\nMentre in passato la maggior parte dei druidi veniva sottoposta a prove prestabilite, il tuo lavoro non avrà niente del genere. Al ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧, c'è stata un'ondata di avvelenamenti tra gli animali, e non riescono a tenerla sotto controllo. Qualcuno laggiù ha chiesto aiuto a ⟦Moonglade=Radaluna⟧, quindi ti mandiamo da loro ad aiutarli. Non è un'esercitazione: il lavoro che farai è del tutto reale. Tienilo a mente.", 0xe3814355, 0xb25e3d68, 0x738324f8, nil, 0x0d09f282, "...m." },
  [6127] = { "La fonte principale", "Usa il ⟦Empty Dreadmist Peak Sampler=Campione del Picco di Brumafunesta Vuoto⟧ per prelevare un campione d'acqua da una pozza in cima al picco.\n\nConsegna il ⟦Filled Dreadmist Peak Sampler=Campione del Picco di Brumafunesta Pieno⟧ a Tonga Runetotem, al ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧.", "Il ⟦Dreadmist Peak=Picco di Brumafunesta⟧, a nord-ovest del ⟦Crossroads=Crocevia⟧, è con ogni probabilità il primo candidato come origine del veleno che si sta diffondendo. Sulle sue cime ventose ci sono pozze d'acqua che influenzano il clima. Sospetto che ora l'acqua sia contaminata dalle ⟦Burning Blade=Lame Ardenti⟧, adoratrici dei demoni.\n\nUsa questo campionatore per prelevare l'acqua dalla pozza in cima al picco. Una volta riempito, consegnalo a Tonga Runetotem, al ⟦Crossroads=Crocevia⟧. È lui che ha chiesto il nostro aiuto, e lavorerai con lui per curare questo male.", "Ti manda il ⟦Cenarion Circle=Circolo Cenariano⟧ di ⟦Moonglade=Radaluna⟧, vero? È davvero provvidenziale per noi! I nostri sforzi per riportare l'equilibrio tra le gazzelle malate che vagano nella parte settentrionale delle ⟦Barrens=Savane⟧ sono in stallo; siamo felici di ricevere tutto l'aiuto possibile.\n\nHai il campione d'acqua che Dendrite Starblaze ha detto che avresti portato? Mi ha avvisato che ne avresti prelevato uno, così da poter lavorare insieme a una cura...", "Per i miei antenati, quest'acqua è disgustosa! Non c'è da stupirsi che le gazzelle siano malate.\n\nQualcosa sta inquinando l'acqua e, di conseguenza, comincia a devastare l'ecosistema della parte settentrionale delle ⟦Barrens=Savane⟧. Sono state avvistate gazzelle malate ovunque a nord della strada est-ovest qui vicino. Anche se quest'acqua è con ogni probabilità una delle fonti principali del male che si diffonde, qui c'è all'opera qualcos'altro.\n\nChe tu ci creda o no, quest'acqua ci aiuterà a preparare una cura. Mentre la studio, mi servono alcuni ingredienti per formulare la cura...", 0xfe91905d, 0xc7e4ec6f, 0x35e50bed, 0x7afc3fe5, 0xa5296c0c, "....." },
  [6128] = { "Gli ingredienti della cura", "Porta 5 Earthroot e 5 Kodo Horn a Tonga Runetotem, al ⟦Crossroads=Crocevia⟧, perché possa preparare un balsamo curativo.", "L'acqua farà da base per il balsamo curativo che preparerò per le gazzelle. Per le proprietà curative mi serve un po' di Earthroot. Gli erboristi sanno come trovarla, quindi, se non conosci quest'arte, dovrai trovarne uno che ci aiuti.\n\nInfine, per renderlo efficace, mi servono corna di kodo: semplici schegge e frammenti non basteranno. I kodo che sei in grado di affrontare vagano nella parte settentrionale delle ⟦Barrens=Savane⟧; abbattine qualcuno per il bene superiore dell'equilibrio, {name}, e portami le corna.", "Hai i reagenti che mi servono per preparare il balsamo? Le gazzelle non migliorano da sole, quindi non dobbiamo indugiare nei nostri sforzi per salvarle!", "Questo va bene, {name}, tanto che dovrebbe bastare a preparare diverse dosi di balsamo, almeno quante ne servono per cominciare a fare la differenza.\n\nPreparare una cura per i veleni a volte può essere molto difficile, perché spesso ognuno richiede un antidoto molto specifico per contrastarlo. Immagina di poter curare un veleno a piacimento senza doverti preoccupare degli ingredienti esatti dell'antidoto!\n\nOra lasciami mettere al lavoro!", 0xc0a4b4dc, 0xc7410c2b, 0x8faf0ffa, 0x38c77760, 0x0d585714, "....." },
  [6129] = { "Curare i malati", "Usa il ⟦Curative Animal Salve=Balsamo Curativo Animale⟧ su 10 Sickly Gazelle sparse per la parte settentrionale delle ⟦Barrens=Savane⟧: dovrebbe guarirle. Le Sickly Gazelle sono state segnalate a nord della strada est-ovest che attraversa il ⟦Crossroads=Crocevia⟧.", "Sono riuscito a preparare abbastanza balsamo per dieci dosi di cura, {name}. Mentre lavoro con le autorità locali per prepararne ancora, vorrei che tu ci aiutassi a portarci avanti. In tutta la parte settentrionale delle ⟦Barrens=Savane⟧ ci sono gazzelle malate; usa il balsamo su di loro e guariscile dal loro male.\n\nSono sicuro che Dendrite Starblaze, a ⟦Moonglade=Radaluna⟧, vorrà parlarti quando avrai finito. Ti prego, porta i nostri ringraziamenti al ⟦Cenarion Circle=Circolo Cenariano⟧ laggiù... e lascia che ti ringrazi io stesso, di persona, per l'aiuto che ci hai dato!", "Hai portato a termine ciò che ti ha chiesto Tonga Runetotem al ⟦Crossroads=Crocevia⟧? Il tuo lavoro non è completo finché non lo farai.", "Hai fatto bene a curare le gazzelle malate delle ⟦Barrens=Savane⟧; sono vittime inconsapevoli di una contaminazione e di una corruzione più grandi che si stanno diffondendo in tutta la terra. Voi tauren siete i più desiderosi di comprendere le vie di Cenarius; tu, come i tuoi anziani a ⟦Thunder Bluff=Picco del Tuono⟧, dimostri che il bisogno di equilibrio trascende le barriere artificiali tra le razze.\n\n{name}, hai dimostrato il tuo valore come amic<o/a> della natura e del Circolo: prendi questo come simbolo.", 0x0116fddd, 0xeeed1d31, 0x6c76cb22, 0x8899d0db, 0x384368d9, "....." },
  [6130] = { "Potere sul veleno", "Torna da Turak Runetotem, sull'⟦Elder Rise=Altura degli Anziani⟧, a ⟦Thunder Bluff=Picco del Tuono⟧.", "Hai imparato cosa significa curare un veleno senza il beneficio dell'aiuto spirituale. Ricorda ciò che gli altri devono sopportare nel combattere le afflizioni velenose, ora che stai per abbracciare il tuo nuovo potere sul veleno.\n\nOra dovresti tornare da Turak Runetotem, a ⟦Thunder Bluff=Picco del Tuono⟧, {name}. Senza dubbio ha un incantesimo molto importante da insegnarti, ora che hai compreso la lezione che ti è stata impartita.\n\nAddio, giovane druid<o/a>. Ci parleremo ancora.", nil, "Bentornat<o/a>. Ho seguito i tuoi progressi in questa lezione da quando sei partit<o/a>, e devo ammettere che mi ha sorpreso sapere della situazione al ⟦Crossroads=Crocevia⟧. La faccenda merita ulteriori indagini, perché l'introduzione di simili veleni nell'ambiente turba profondamente l'equilibrio.\n\nHai mantenuto grazia e sangue freddo sotto pressione. Per questo, non trovo modo migliore per ricompensarti che con un potere permanente sul veleno. Usalo bene, {name}... usalo bene.", 0xfaefb521, 0xeb5d1d3a, 0x2d5f79f7, nil, 0x0b177411, "...m.", nil, nil, 0x2bc5137a, nil, nil },
  [6181] = { "Un messaggio rapido", "Porta la ⟦Lewis' Note=Nota di Lewis⟧ a Thor, il maestro dei grifoni.", "Anche se da ⟦Stormwind=Roccavento⟧ non riceviamo molti aiuti diretti, in città ho un contatto che ci rifornisce di armature. Si chiama Osric Strang. La sua bottega, Limited Immunity, è nella Old Town di ⟦Stormwind=Roccavento⟧.\n\nLe nostre scorte di armature si stanno esaurendo e devo chiederne altre a Osric. Puoi portargli questa nota?\n\nIl modo più rapido per arrivare a ⟦Stormwind=Roccavento⟧ è tramite Thor, il nostro maestro dei grifoni. Sta giù in fondo alla collina: portagli la mia nota, poi prendi un grifone per ⟦Stormwind=Roccavento⟧.", "Sembri di fretta. Be', allora sei nel posto giusto!", "Devi portare questa nota a ⟦Stormwind=Roccavento⟧? Nessun problema, puoi prendere uno dei miei grifoni!", 0xd0027ff1, 0xacee0705, 0x971b5160, 0x5c4d4ffe, 0x13821bcd, "....." },
  [6261] = { nil, "Porta la ⟦Osric's Crate=Cassa di Osric⟧ a Dungar Longdrink, il maestro dei grifoni.", "{name}, ho messo in questa cassa tutto ciò che Lewis ha chiesto. Puoi portargliela?\n\nSe hai già parlato con Thor nelle ⟦Westfall=Marche Occidentali⟧, puoi prendere un grifone per tornare da lui. Dungar Longdrink è il nostro maestro dei grifoni, laggiù nel Quartiere del Commercio.\n\nParla con Dungar, poi porta questa cassa a Lewis il più in fretta possibile. Non vogliamo che i nostri uomini e le nostre donne al fronte nelle ⟦Westfall=Marche Occidentali⟧ restino senza equipaggiamento nuovo!", "È sudore quello sulla tua fronte, <ragazzo/signora>? Hai corso troppo. La prossima volta prendi un grifone!", "Una cassa per le ⟦Westfall=Marche Occidentali⟧, eh? Ci sei già stat<o/a>, nelle ⟦Westfall=Marche Occidentali⟧? Se sì, nessun problema, <amico/amica>. Ho un sacco di grifoni addestrati per quella rotta!", 0x99cf1567, 0x7f71eb16, 0x150a7f07, 0xd7a18628, 0xfce80486, "e....", nil, nil, nil, 0x276c0f6b, nil },
  [6281] = { "Verso ⟦Stormwind=Roccavento⟧", "Paga un volo in grifone al maestro dei grifoni Thor, poi porta la ⟦Lewis' Note=Nota di Lewis⟧ a Osric Strang, nella bottega Limited Immunity, nella Old Town di ⟦Stormwind=Roccavento⟧.", "Per una piccola somma puoi prendere un grifone per ⟦Stormwind=Roccavento⟧ e consegnare la nota di Lewis a Osric. Non ci arriverai più in fretta in nessun altro modo.\n\nSe ti va bene, parla di nuovo con me quando sei pront<o/a> per il volo. Ti chiederò qualcosa, ma fidati: ne varrà la pena!", "Sei stat<o/a> in viaggio, eh? Sei andat<o/a> da qualche parte di interessante?", "Ah, una nota del furiere Lewis? Non mi sorprende che gli serva altro equipaggiamento. ⟦Sentinel Hill=Guardiacolle⟧ è lontana, in una terra che ⟦Stormwind=Roccavento⟧ ha quasi dimenticato.\n\nBe', grazie, {name}. Ecco un po' di denaro per coprire le spese di viaggio.", 0x950eaddd, 0x9a2be79a, 0xd7241ffb, 0xd55888b8, 0x83dfa7ed, "....." },
  [6285] = { "Ritorno da Lewis", "Paga un volo in grifone per ⟦Sentinel Hill=Guardiacolle⟧ al maestro dei grifoni Dungar Longdrink, poi porta la ⟦Osric's Crate=Cassa di Osric⟧ a Lewis a ⟦Sentinel Hill=Guardiacolle⟧.", "Il maestro dei grifoni nelle ⟦Westfall=Marche Occidentali⟧ è Thor. Se ci hai già parlato, puoi prendere uno dei miei grifoni per raggiungerlo.\n\nÈ una buona lezione da imparare: i grifoni sono sempre addestrati a volare verso la loro capitale, ma ti porteranno da un maestro dei grifoni lontano solo dopo che ci sei già stat<o/a>.\n\nSei già stat<o/a> da Thor, quindi parla di nuovo con me quando sei pront<o/a> a prendere un grifone per le ⟦Westfall=Marche Occidentali⟧. Una volta lì, potrai consegnare la ⟦Osric's Crate=Cassa di Osric⟧ al furiere Lewis.", "Sei tornat<o/a> da ⟦Stormwind=Roccavento⟧? Osric ha mandato le armature?", "Ottimo, hai portato le armature! Le distribuiremo subito a chi ne ha bisogno.\n\nGrazie, {name}. I tuoi sforzi ci sono stati di grande aiuto. E ora che i grifoni non sono più una novità per te, spero che verrai spesso a dare una mano a ⟦Sentinel Hill=Guardiacolle⟧!", 0x96f66445, 0x1c7c566e, 0xb428ac6f, 0x54a54947, 0xb877172b, "....." },
  [6321] = { "Rifornimenti per la ⟦Sepulcher=Mausolea⟧", "Porta Podrig's Order a Karos Razok.", "L'esecutore Hadrec mi ha chiesto di fare l'inventario del nostro equipaggiamento alla ⟦Sepulcher=Mausolea⟧. Con il Flagello, e di peggio, in agguato nei boschi, non vuole che alle Guardie della Morte manchi l'equipaggiamento di cui potrebbero aver bisogno.\n\nHo scoperto che, in generale, siamo ben riforniti, ma ci servono altre armi per sostituire quelle perse sul campo.\n\nEcco un ordine di requisizione con ciò che serve, per il mercante d'armi Gordon Wendham a ⟦Undercity=Sepulcra⟧. Porta l'ordine al nostro maestro dei pipistrelli, Karos Razok, e parla con lui del trasporto fino a ⟦Undercity=Sepulcra⟧.", "Hai l'aria di chi è qui per affari ufficiali...", "Ah, un ordine di rifornimenti. Vorrai portarlo a ⟦Undercity=Sepulcra⟧, senza dubbio. E in fretta, perché la ⟦Sepulcher=Mausolea⟧ non deve restare a corto di scorte.", 0xcfcc9350, 0xe5b2c631, 0x954541ad, 0x048ed251, 0x09aef9bb, "....." },
  [6322] = { nil, "Porta la ⟦Gordon's Crate=Cassa di Gordon⟧ a Michael Garrett.", "Ho messo le provviste per la ⟦Sepulcher=Mausolea⟧ in questa cassa. Se hai già visitato la ⟦Sepulcher=Mausolea⟧ e parlato con il loro maestro dei pipistrelli, puoi tornare da lui in pipistrello.\n\nParla con il maestro dei pipistrelli di Sepulcra, Michael Garrett. Può darti un pipistrello per la ⟦Sepulcher=Mausolea⟧.", "Se devi percorrere una lunga distanza, il pipistrello è la scelta migliore.", "Questa cassa deve arrivare alla ⟦Sepulcher=Mausolea⟧, a ⟦Silverpine=Pinargento⟧? È facile: i nostri pipistrelli ci volano ogni giorno.", 0x30ec3f6a, 0x230e74d9, 0xc7c7a93c, 0xd08ea5ce, 0x0dfb1564, "e...." },
  [6323] = { "In volo verso ⟦Undercity=Sepulcra⟧", "Paga un volo in pipistrello per ⟦Undercity=Sepulcra⟧ al maestro dei pipistrelli Karos Razok, poi porta Podrig's Order a Gordon Wendham a ⟦Undercity=Sepulcra⟧.", "Uno dei miei pipistrelli può portarti a ⟦Undercity=Sepulcra⟧, per una piccola somma. Parla di nuovo con me quando sei pront<o/a>, così potremo organizzare il tuo trasporto.\n\nTroverai Gordon Wendham nel ⟦Trade Quarter=Quartiere del Commercio⟧ di ⟦Undercity=Sepulcra⟧. È lo stesso quartiere dove atterrerà il mio pipistrello.", "Tengo le mie armi in perfette condizioni. Sono pulite e pronte all'uso.", "Un ordine dalla ⟦Sepulcher=Mausolea⟧? Molto bene. È un onore servire chi serve la nostra Dama Oscura.", 0x5760d29a, 0x3400fc7c, 0x02b18c1a, 0xf820d1e4, 0x2b5a74f3, "....." },
  [6324] = { "Ritorno da Podrig", "Paga un volo in pipistrello per la ⟦Sepulcher=Mausolea⟧ al maestro dei pipistrelli Michael Garrett, poi porta la ⟦Gordon's Crate=Cassa di Gordon⟧ alla Guardia della Morte Podrig alla ⟦Sepulcher=Mausolea⟧.", "Il maestro dei pipistrelli della ⟦Sepulcher=Mausolea⟧ è Karos Razok. Se l'hai già incontrato, posso darti un pipistrello per tornare da lui.\n\nI nostri pipistrelli voleranno sempre verso ⟦Undercity=Sepulcra⟧, ma per raggiungere località più remote chi li cavalca deve prima visitare la zona e parlare con il suo maestro dei pipistrelli.\n\nHai incontrato Karos alla ⟦Sepulcher=Mausolea⟧, quindi ora puoi volarci in pipistrello. Parla di nuovo con me quando sei pront<o/a>.", "{name}, sei tornat<o/a>. Hai le nostre provviste da ⟦Undercity=Sepulcra⟧?", "Buon lavoro, {name}. Queste armi faranno sì che le nostre Guardie della Morte non vengano colte impreparate.\n\nHai reso un prezioso servizio alla nostra Dama Oscura.", 0xdb263293, 0x62f053a2, 0x2d4da181, 0x34df7e4c, 0x61e021f3, "....." },
  [6341] = { "L'abbondanza di Teldrassil", "Porta Nessa's Collection a Vesprystus.", "I pescatori del villaggio di Rut'theran se la passano molto bene, perché qui i pesci sono enormi e abbondanti. Vorrei confrontare l'abbondanza di qui con quella del continente.\n\nHo una raccolta di lische e squame che vorrei far arrivare a un mio collega a ⟦Darkshore=Rivafosca⟧. Si chiama Laird ed è un pescivendolo nel villaggio di Auberdine.\n\nPorta la mia raccolta al nostro maestro degli ippogrifi, Vesprystus, e parla con lui del viaggio fino ad Auberdine.", "Come posso aiutarti? Ti serve un passaggio?", "Ah, vuoi portare questa ad Auberdine? Molto bene...", 0xfdaa45cb, 0x849cfb5d, 0xeffe6b5d, 0x2fd3c26c, 0x82c592b4, "....." },
  [6342] = { "Volo per Auberdine", "Vola in ippogrifo fino ad Auberdine con il maestro degli ippogrifi Vesprystus, poi porta Nessa's Collection a Laird.", "Da Rut'theran ci sono due modi per raggiungere Auberdine: il traghetto e l'ippogrifo. Entrambi sono rapidi e affidabili, ma se non hai ancora volato fino ad Auberdine in ippogrifo, ti consiglio di farlo.\n\nÈ un buon consiglio parlare con il maestro degli ippogrifi di ogni città che ne ha uno. Una volta che avrai parlato con il maestro, potrai volare lì dalle altre città.\n\nEcco la raccolta di Nessa. Parla di nuovo con me quando sei pront<o/a> a volare fino ad Auberdine per consegnare la raccolta di Nessa a Laird.", "Vieni da Teldrassil? Dimmi, com'è la pesca laggiù?", "Un pacco da Nessa? Grazie, {name}! Mi aveva detto che mi avrebbe mandato dei campioni dei pesci pescati vicino al villaggio di Rut'theran. Pensa che possano essere molto diversi dai pesci pescati qui...\n\nPerbacco! Questa mandibola è grande quasi il doppio di quella dello stesso pesce trovato qui. E queste squame sono grandi come un pugno chiuso! Incredibile!", 0xdcb4055c, 0xedfc0608, 0xf7020ff1, 0x289d443c, 0xa33b905a, "....." },
  [6343] = { "Ritorno da Nessa", "Porta Laird's Response a Nessa Shadowsong.", "Devo mandare una risposta a Nessa. Sarà molto interessata a sapere quanto sono diversi i pesci di qui da quelli lungo le coste di Teldrassil. Possiamo solo fare ipotesi sulla causa, ma sospetto che sia l'Albero del Mondo stesso a influire sulla fauna che lo circonda!\n\nTi prego, porta questa risposta a Nessa. Se vuoi prendere un ippogrifo per tornare a Rut'theran, parla con il maestro degli ippogrifi Caylais Moonfeather. Se preferisci il traghetto, ne parte regolarmente uno dal molo a nord-ovest.", "{name}, sei tornat<o/a> da Auberdine? Hai parlato con Laird?", "È molto interessante. I pesci qui sono grandi, ma non pensavo che la differenza di abbondanza tra qui e il continente fosse così marcata. Dev'esserci una ragione...\n\nBe', grazie, {name}. Discuterò con gli abitanti del villaggio delle notizie che hai portato. Forse, un giorno, scopriremo la radice di questa stranezza. Ma fino ad allora, ne godremo i frutti!", 0xba10c9cf, 0x9efa6697, 0x2381f0ae, 0x47a9c3c4, 0x4e30b81a, "....." },
  [6344] = { nil, "Parla con Nessa Shadowsong.", "Una mia amica, Nessa Shadowsong, è una mercante di pesce a ⟦Rut'theran Village=Rut'theran⟧. Ha bisogno che qualcuno porti un pacco a ⟦Darkshore=Rivafosca⟧ e cerca chi possa aiutarla.\n\nSe ti interessa, per raggiungere Nessa devi prendere il portale di Darnassus che porta a ⟦Rut'theran Village=Rut'theran⟧. Troverai il portale a ovest dei Temple Gardens.", nil, "Sì, ho bisogno di un corriere che porti un pacco a ⟦Darkshore=Rivafosca⟧. Mi aiuterai?", 0x1cde2001, 0x0db93fa5, 0x3d0373e4, nil, 0xaae17e8e, "e..m." },
  [6361] = { "Un ⟦Bundle of Hides=Mucchio di Pelli⟧", "Porta il ⟦Bundle of Hides=Mucchio di Pelli⟧ al maestro delle viverne Devrak a ⟦Crossroads=Crocevia⟧.", "Ho un mucchio di pelli degli animali delle ⟦Barrens=Savane⟧ e devo farle arrivare a ⟦Thunder Bluff=Picco del Tuono⟧. Un collega laggiù, Ahanu, userà le pelli per creare articoli di cuoio.\n\nPorteresti le pelli a lui per me?\n\nIl modo più rapido per arrivare a ⟦Thunder Bluff=Picco del Tuono⟧ è in groppa a una viverna. Porta il mucchio di pelli a Devrak, il nostro maestro delle viverne a ⟦Crossroads=Crocevia⟧, e parla con lui del trasporto fino a ⟦Thunder Bluff=Picco del Tuono⟧.", "Sei qui per una viverna? Hai qualcosa da trasportare?", "Se devi portare queste pelli a ⟦Thunder Bluff=Picco del Tuono⟧, stai parlando con l'orco giusto!", 0x5629a678, 0x83576182, 0x83c7dd76, 0xc0c44b7a, 0x5fdeeba3, "....." },
  [6362] = { "In volo verso ⟦Thunder Bluff=Picco del Tuono⟧", "Paga una viverna per ⟦Thunder Bluff=Picco del Tuono⟧ al maestro delle viverne Devrak, poi porta il ⟦Bundle of Hides=Mucchio di Pelli⟧ ad Ahanu a ⟦Thunder Bluff=Picco del Tuono⟧.", "Per una piccola somma ti darò una viverna per ⟦Thunder Bluff=Picco del Tuono⟧. Non c'è modo più rapido per raggiungere la città!\n\nSe ti va bene, parla di nuovo con me quando sei pront<o/a> a partire.\n\nSe porti quelle pelli ad Ahanu, credo che sia alla Hewa's Armory, ai piedi della torre delle viverne di ⟦Thunder Bluff=Picco del Tuono⟧. Ed è proprio lì che atterrerai!", "Hai sulle spalle della polvere che deve venire dalle ⟦Barrens=Savane⟧. Hai parlato con il mio amico Jahan?", "Ah, un nuovo mucchio di pelli. Mi ci metto subito al lavoro!\n\nGrazie, <fratello/sorella>. Mi hai reso un grande servizio. Ecco qualche moneta per il tuo tempo e le spese di viaggio.", 0x17e56cf3, 0xdb3baab4, 0xa2c8ef96, 0x26fbf800, 0x24706f90, ".....", nil, nil, nil, nil, 0x6bd5e885 },
  [6363] = { "Tal, maestro delle viverne", "Porta le ⟦Ahanu's Leather Goods=Mercanzie di Pelle di Ahanu⟧ a Tal a ⟦Thunder Bluff=Picco del Tuono⟧.", "Ho preparato degli articoli di cuoio che Jahan venderà a ⟦Crossroads=Crocevia⟧. Glieli porteresti?\n\nSe sei già stat<o/a> a ⟦Crossroads=Crocevia⟧ e hai parlato con il loro maestro delle viverne, puoi tornare da lui con una delle nostre viverne di ⟦Thunder Bluff=Picco del Tuono⟧.\n\nPorta gli articoli di cuoio a Tal, il nostro maestro delle viverne a ⟦Thunder Bluff=Picco del Tuono⟧, e parla con lui per organizzare il trasporto fino a ⟦Crossroads=Crocevia⟧.", "Salve, {class}. Cosa posso fare per te?", "Devi portare questa roba a ⟦Crossroads=Crocevia⟧, eh? Nessun problema. Se ci sei già stat<o/a> e hai parlato con Devrak, puoi prendere una delle mie viverne per tornare da lui.", 0xf7fcbd33, 0xf87319fc, 0x14bf81fc, 0xaf415926, 0xd7505c5d, "....." },
  [6364] = { "Ritorno da Jahan", "Paga una viverna per ⟦Crossroads=Crocevia⟧ al maestro delle viverne Tal, poi porta le ⟦Ahanu's Leather Goods=Mercanzie di Pelle di Ahanu⟧ a Jahan Hawkwing.", "Per volare verso una città devi esserci già stat<o/a> e aver parlato con il suo maestro delle viverne. Sei stat<o/a> a ⟦Crossroads=Crocevia⟧ e hai parlato con il loro maestro delle viverne, Devrak, quindi per una piccola somma puoi prendere una viverna da qui per raggiungerlo.\n\nParla di nuovo con me quando sei pront<o/a>. Una volta a ⟦Crossroads=Crocevia⟧, potrai consegnare gli articoli di cuoio a Jahan Hawkwing.", "{name}, sei tornat<o/a> da ⟦Thunder Bluff=Picco del Tuono⟧? Hai consegnato le pelli ad Ahanu?", "Ahanu mi ha mandato i prodotti finiti? Molto bene. Ci sono molti cacciatori e avventurieri a ⟦Crossroads=Crocevia⟧ adesso, e gli affari vanno a gonfie vele. Sono sicuro che venderò questa merce molto presto.\n\nGrazie per tutti i tuoi sforzi, {name}. Ti sono debitore.", 0x734dcf93, 0x7a7dc803, 0xca30143e, 0xfdd2709f, 0x30c7484a, "....." },
  [6365] = { "Carne per Orgrimmar", "Porta Zargh's Meats a Devrak a ⟦Crossroads=Crocevia⟧.", "Ho dei tagli di carne scelti da mandare a un'amica. Si chiama Gryshka, è la locandiera di Orgrimmar. Me la consegni tu la carne?\n\nIl modo più rapido per arrivare a Orgrimmar è in viverna. Porta la carne al maestro delle viverne di ⟦Crossroads=Crocevia⟧, Devrak, e parla con lui del trasporto fino a Orgrimmar.", "Devi arrivare da qualche parte in fretta? Allora stai parlando con l'orco giusto!", "Devi portare questa carne a Orgrimmar? Nessun problema. Per una piccola somma, la mia viverna può portartici.", 0x192a86fc, 0x81387def, 0xb0f8daee, 0xb3f83d0e, 0x16ed8259, "....." },
  [6382] = { "La caccia di ⟦Ashenvale=Valtetra⟧", "Parla con Senani Thunderheart all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a ⟦Ashenvale=Valtetra⟧.", "La tua forza mi colpisce, {class}. La tua disponibilità ad abbracciare la caccia mi dà fiducia che potresti passare a prede più grosse... e a sfide più grandi.\n\nLe foreste di ⟦Ashenvale=Valtetra⟧ sono una vasta terra selvaggia e indomita su cui l'⟦Horde=Orda⟧ cerca di imporre la propria volontà, sia politica che spirituale. Se vuoi dimostrare il tuo valore in una terra ancora da conquistare, cerca la guida di Senani Thunderheart all'⟦Splintertree Post=Avamposto di Troncorotto⟧. L'avamposto si trova dritto a nord del sentiero che arriva dalle ⟦Barrens=Savane⟧.", nil, "Benvenut<o/a> nella nuova frontiera, {name}. ⟦Ashenvale=Valtetra⟧ è una terra di opportunità, dove un giovane {class} come te può trovare infinite occasioni per dimostrare il proprio valore. Dai un'occhiata all'avamposto e non mancare di spingerti fino alla ⟦Zoram Strand=Spiaggia di Zoram⟧, dove l'⟦Horde=Orda⟧ ha un altro avamposto.\n\nLa tua presenza qui mi dice che sei <venuto/venuta> per saperne di più sulla caccia. Ascolta bene, e ti dirò volentieri ciò che devi sapere.", 0x1bf465b8, 0x0a003978, 0xe968293f, nil, 0xedbc036b, "...m." },
  [6383] = { "La caccia di ⟦Ashenvale=Valtetra⟧", nil, nil, nil, "Sono tre le creature leggendarie che compongono la caccia di ⟦Ashenvale=Valtetra⟧; puoi cercarle e misurarti con la loro astuzia e la loro forza. Così facendo, spero, imparerai qualcosa su te stess<o/a>. Le creature sono: l'orso Ursangous, il felino notturno Shadumbra e l'ippogrifo Sharptalon.\n\nLe creature della caccia di ⟦Ashenvale=Valtetra⟧ sono potenti, e potresti scoprire di aver bisogno di aiuto per abbatterle. Se riuscirai a sconfiggerle, portami la prova della tua impresa.", 0x1bf465b8, nil, nil, nil, 0x91a48cae, ".mmm." },
  [6384] = { "In volo verso Orgrimmar", "Paga una viverna per Orgrimmar al maestro delle viverne Devrak, poi porta Zargh's Meats a Gryshka a Orgrimmar.", "Per poche monete farò in modo che una viverna ti porti a Orgrimmar. Quando arrivi, puoi consegnare la carne di Zargh a Gryshka. La sua locanda è nella ⟦Valley of Strength=Valle della Forza⟧, non lontano dalla Skytower, dove ti lascerà la mia viverna.\n\nParla di nuovo con me quando sei pront<o/a> per il viaggio.", "Che buon profumo! Non avrai mica della carne cruda addosso, vero?", "Oh, meraviglioso! Che tagli pregiati! Vengono da Zargh, vero? Quell'orco sa proprio come conquistare il cuore di una signora...\n\nOh, non vedo l'ora di cucinarla. Ma non troppo! La carne va servita al sangue, non credi?", 0x09e2c4f0, 0x68c9187c, 0x8879a481, 0x94e76fb4, 0x7fe221c3, "....." },
  [6385] = { "Doras, maestro delle viverne", "Porta la ⟦Gryshka's Letter=Lettera di Gryshka⟧ a Doras a Orgrimmar.", "Ho scritto una lettera di ringraziamento per Zargh. Me la consegneresti? Se sei già stat<o/a> a ⟦Crossroads=Crocevia⟧ e hai parlato con il loro maestro delle viverne, puoi tornarci in viverna.\n\nPorta la mia lettera a Doras, il maestro delle viverne di Orgrimmar, e parla con lui del trasporto fino a ⟦Crossroads=Crocevia⟧.", "Ti serve una delle mie viverne?", "Devi portare questa a ⟦Crossroads=Crocevia⟧, nelle ⟦Barrens=Savane⟧? Sì, posso portartici...", 0x9897a748, 0x9e96cb95, 0x96a2b1e4, 0x4b572cc6, 0xf84cda5f, "....." },
  [6386] = { "Ritorno a ⟦Crossroads=Crocevia⟧", "Paga una viverna per ⟦Crossroads=Crocevia⟧ al maestro delle viverne Doras, poi porta la ⟦Gryshka's Letter=Lettera di Gryshka⟧ a Zargh a ⟦Crossroads=Crocevia⟧.", "Le mie viverne sono addestrate a volare in molti luoghi diversi, purché tu ci sia già stat<o/a> e abbia parlato con il maestro delle viverne del posto.\n\nSei stat<o/a> a ⟦Crossroads=Crocevia⟧ e hai parlato con il loro maestro delle viverne, Devrak, quindi ora puoi volare direttamente da lui da qui. Una volta a ⟦Crossroads=Crocevia⟧, potrai consegnare la Lettera di Gryshka a Zargh.\n\nParla con me quando sei pront<o/a> a partire.", "Sei tornat<o/a> da Orgrimmar? A Gryshka è piaciuta la carne che le ho mandato?", "Ah! Direi che le è piaciuta! Niente fa arrossire le guance di una signora come una bella bistecca succosa!\n\nGrazie, {name}. Mi hai reso un grande servizio. Ecco un po' di denaro per il disturbo, e non stupirti se ti inviterò al mio matrimonio!", 0xb7e37b1d, 0xd651c4fc, 0x3d58c10b, 0x46394cd6, 0x69eb2cba, "....." },
  [6387] = { "Studenti meritevoli", "Porta Brock's List a Thorgrum Borrelson a Thelsamar.", "Vedo un sacco di giovani nani alla mia porta, ansiosi di imparare il mestiere del minatore. E se c'è una cosa di cui un minatore ha bisogno più di ogni altra, è un piccone!\n\nHo una lista di studenti di estrazione mineraria che hanno preso voti alti alle lezioni e si sono guadagnati un piccone d'onore. Porta la mia lista a Golnir Bouldertoe a ⟦Ironforge=Forgiardente⟧. Lui preparerà i picconi.\n\nIl modo più rapido per arrivare a ⟦Ironforge=Forgiardente⟧ è in grifone, quindi porta la lista al nostro maestro dei grifoni, Thorgrum Borrelson, e parla con lui del trasporto fino a ⟦Ironforge=Forgiardente⟧.", "Ne hai già abbastanza di Thelsamar? Sei pront<o/a> a partire per un'altra città?", "Devi portare questa a ⟦Ironforge=Forgiardente⟧, eh? Per una piccola somma posso metterti in groppa a uno dei miei grifoni, e ti porterà lì. Che ne dici?", 0x24e749d7, 0xf62403c1, 0x57e23adf, 0x093769d9, 0xedf1dc2f, "....." },
  [6388] = { nil, "Porta gli Honorary Picks a Gryth Thurden a ⟦Ironforge=Forgiardente⟧.", "Ecco i picconi d'onore per gli studenti di Brock. Se sei già stat<o/a> a Thelsamar, dovresti tornarci in grifone!\n\nPorta i picconi al nostro maestro dei grifoni, Gryth Thurden, e parla con lui di un passaggio per tornare a Thelsamar.", "Hai l'aria di chi deve andare da qualche parte. Ti serve uno dei miei grifoni?", "Devi portare questi a Thelsamar, eh? Non sarà un problema. Se sei già stat<o/a> a Thelsamar e hai parlato con Thorgrum Borrelson, puoi prendere uno dei miei grifoni per tornare da lui.", 0x3b5086d2, 0x029c72cb, 0xc7801ddb, 0x4e09c9af, 0x721a7bfa, "e...." },
  [6391] = { "In volo verso ⟦Ironforge=Forgiardente⟧", "Paga un grifone per ⟦Ironforge=Forgiardente⟧ al maestro dei grifoni Thorgrum Borrelson, poi porta Brock's List a Golnir Bouldertoe a ⟦Ironforge=Forgiardente⟧.", "Per poche monete, uno dei miei grifoni ti porterà a ⟦Ironforge=Forgiardente⟧. Da lì, consegna la lista di Brock a Golnir Bouldertoe. Lo troverai nella Deep Mountain Mining Guild. Si trova nel distretto della ⟦Great Forge=Grande Forgia⟧ di ⟦Ironforge=Forgiardente⟧, proprio dove ti lascerà il mio grifone!\n\nParla di nuovo con me quando sei pront<o/a> per il viaggio.", "Cosa posso fare per te, <signore/signora>?", "Ah, l'ultima lista dei migliori allievi di Brock. Ho una partita di picconi d'onore pronta. Devo solo incidere i nomi degli studenti...", 0xd28081ed, 0x0477c979, 0x2cfa2e26, 0x92c650dc, 0xe778e783, ".....", nil, nil, nil, 0xd6deda79, nil },
  [6392] = { "Ritorno da Brock", "Compra un volo in grifone per Thelsamar dal maestro di grifoni Gryth Thurden, poi porta gli Honorary Picks a Brock Stoneseeker, a Thelsamar.", "Con una piccola somma puoi comprare un volo in grifone fino a Thelsamar... sempre che tu ci sia già <stato/stata>. I grifoni ti portano solo nei posti dove sei già <stato/stata>, quindi assicurati di parlare con ogni maestro di grifoni che incontri, così potrai volare da lui in seguito.\n\nSei già <stato/stata> da Thorgrum, il maestro di grifoni di Thelsamar, quindi ora puoi tornare da lui. E una volta a Thelsamar, potrai consegnare i picconi a Brock Stoneseeker.\n\nParla con me quando sei <pronto/pronta> a partire.", "Ah, {name}. Sei <tornato/tornata> da ⟦Ironforge=Forgiardente⟧?", "Hai portato i picconi. Ottimo! Li darò ai miei allievi minatori. Sono sicuro che non vedono l'ora di usarli sui giacimenti di Loch Modan.\n\nGrazie per il tuo aiuto, {name}. Sono in debito con te, ma spero che questo denaro copra almeno le spese di viaggio.", 0xe9291a93, 0xd370798c, 0x72505319, 0x7b4723d5, 0xf9547062, "....." },
  [6394] = { "⟦Thazz'ril's Pick=Piccone di Thazz'ril⟧", "Porta il ⟦Thazz'ril's Pick=Piccone di Thazz'ril⟧ al caposquadra Thazz'ril.", "{name}, sei un {race} affidabile. Posso contare su di te per un altro compito?\n\nTempo fa stavo esplorando la grotta a nord in cerca di minerali e ho dimenticato lì il mio piccone preferito. Quando sono tornato a riprenderlo, ho trovato la grotta piena di bestie feroci! Andresti nella grotta, il ⟦Burning Blade Coven=Covo delle Lame Ardenti⟧, a recuperare il mio piccone?\n\nL'ho lasciato in una caverna con delle cascate. Sul mio piccone c'è un incantesimo che lo rende visibile al buio, quindi non dovrai preoccuparti di trovarlo... solo di ciò che lo sorveglia!", "Sei entrat<o/a> nel ⟦Burning Blade Coven=Covo delle Lame Ardenti⟧, {name}? Hai trovato il mio piccone?", "Grande, l'hai trovato! Grazie mille, {name}. È il mio piccone preferito! Ora, se i miei peoni finiranno mai di abbattere questi alberi, forse potremo trovare una bella grotta da scavare!", 0xcb16d6a3, 0x42cbea5f, 0x69e4753a, 0x8afd7942, 0x66e27461, "....." },
  [6395] = { "L'ultimo desiderio di Marla", "Porta i Samuel Fipps' Remains alla tomba di Marla, poi torna dalla novizia Elreth.", "La mia amica Marla Fipps viveva con suo marito Samuel prima della pestilenza, ma quando arrivò la pestilenza Samuel soccombette e si unì alle file del Flagello.\n\nMarla fu risparmiata dalla non morte, solo per morire per mano di suo marito, ormai senza mente. Il suo amore però era così forte che il suo ultimo desiderio fu di essere sepolta con il suo amato Samuel.\n\nSamuel Fipps vaga in un accampamento in rovina lungo la strada a nord-est di ⟦Deathknell=Albamorta⟧. Sconfiggilo ed esaudisci il desiderio di Marla: seppelliscilo nella sua tomba, nella prima fila del nostro cimitero.", "Dobbiamo rispettare i nostri morti, {name}. È uno dei modi in cui siamo diversi dal Flagello...", "Oggi hai compiuto una buona azione, {name}. Anche se la nostra lotta contro il Flagello continua, speriamo che Marla e Samuel trovino pace insieme nel loro ultimo luogo di riposo.", 0x3ab505f6, 0x48105831, 0xe3b59356, 0xae4dd1f3, 0xfb9bd7b5, "....." },
  [6401] = { "Kaya è viva", "Porta la buona notizia a Tammra Windfield, al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧.", "Porta la buona notizia a Tammra Windfield, la zia di Kaya, che si trova al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧! Kaya è viva! La credevamo perduta dopo il brutale attacco al nostro villaggio. Segui il sentiero verso ovest per arrivare al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧.", nil, "Santo cielo, mia nipote Kaya è viva! È davvero una bella notizia. Grazie, {name}.", 0x29fb8709, 0x1e4fb9d8, 0x9edc231d, nil, 0xce73e720, "...m." },
  [6421] = { "⟦Boulderslide Ravine=Gola dei Franamassi⟧", "Esplora a fondo la caverna della ⟦Boulderslide Ravine=Gola dei Franamassi⟧ e riporta 10 Resonite Crystal a Mor'rogal, al ⟦Sun Rock Retreat=Rifugio Roccia del Sole⟧, perché possa esaminarli.", "Qualcosa non va qui a ⟦Stonetalon=Petrartiglio⟧. Senti la tensione nell'aria, {name}?\n\nA sud-est di qui, nella ⟦Boulderslide Ravine=Gola dei Franamassi⟧, c'è una caverna profonda. I coboldi là dentro stanno estraendo freneticamente un cristallo raro chiamato Resonite. Ho bisogno che tu mi porti qualche campione di minerale, così che io possa capire cosa sta succedendo in quella caverna. Devo anche sapere quanto è profonda.\n\nVa', giovane {class}: è fondamentale che io sappia quale male si annida sotto queste montagne.", "Che notizie hai scoperto nella ⟦Boulderslide Ravine=Gola dei Franamassi⟧? Ricordo una leggenda che riguarda la Resonite... ma proprio non riesco a metterci lo zoccolo sopra. Forse sapere cosa si trova in fondo alla caverna farà luce sulle loro subdole intenzioni.", "Ah... Sì! Ecco cos'è: i cristalli di Resonite contengono una traccia di magia Terrigena. I coboldi devono aver scavato in profondità e portato alla luce un Terrigeno.\n\nLa leggenda narra che i Terrigeni siano creature create dai Titani. Furono usati per plasmare la terra su cui camminiamo. Questa è senza dubbio una minaccia che non si può ignorare.\n\n<Mor'rogal scuote la testa.>\n\nForse posso incantare questi campioni di minerale per usarli contro il piano dei coboldi.", 0xafc62dde, 0x052e328b, 0x4270ef12, 0x9806d736, 0x1da30e95, "....." },
  [6442] = { "Naga alla ⟦Zoram Strand=Spiaggia di Zoram⟧", "Porta 20 Wrathtail Head a Marukai, lungo la ⟦Zoram Strand=Spiaggia di Zoram⟧.", "Il male si annida qui lungo la costa, {race}.\n\nLì riposa la città perduta di Zoram, distrutta tanto tempo fa e sommersa dai mari. Perduta, e quasi dimenticata.\n\nOra i naga sono tornati, e non sappiamo per quale motivo. Ma il motivo conta poco: dobbiamo difendere la terra che abbiamo tanto faticato a conquistare.\n\nTorna da me con 20 delle loro teste! Ricaccia i naga negli abissi!", "I naga aumentano di numero, {name}. Ti prego, porta a termine questo compito per me.", "Ci servirebbero più tipi come te da queste parti, {name}. Grazie per l'aiuto.", 0x4fd49e58, 0x910e5478, 0x1629860a, 0x3e533dbd, 0x06b6f56f, "....." },
  [6461] = { "Succhiasangue", "Xen'zilla, a Malaka'Jin, ha bisogno che tu uccida 10 Deepmoss Creeper e 7 Deepmoss Venomspitter.", "Noi Troll qui a Malaka'Jin abbiamo prosperato grazie alla terra; le montagne di ⟦Stonetalon=Petrartiglio⟧ offrono ottima caccia per vivere.\n\nUltimamente però abbiamo attirato gli ospiti a cena sbagliati... i ragni di queste montagne assaltano i nostri accampamenti di notte per rubarci le prede.\n\nSe ci aiutassi a sterminare queste bestie orrende, noi di Malaka'Jin saremmo in debito con te. I ragni sono dappertutto a ⟦Stonetalon=Petrartiglio⟧: basta che vai a nord da qui e capirai di cosa parlo.", "Ehi, amico, hai fatto fuori quei pelosi succhiasangue? Io non temo niente qui a ⟦Stonetalon=Petrartiglio⟧, ma di notte non me ne vado in giro... se capisci cosa intendo, amico!\n\nFinché non finisco nel loro piatto, va tutto bene.\n\nBuona fortuna, {class}!", "Grande, amico! Buone notizie: forse stanotte avremo meno ospiti indesiderati a cena.\n\nMolte grazie, {name}. Saremo per sempre in debito con te.", 0x290dc497, 0x3dbb349e, 0x44275372, 0xf8a245cd, 0x831e4ebe, "....." },
  [6481] = { "Sorgi, Terrigeno", "Apri il barile di Resonite con il ⟦Enchanted Resonite Crystal=Cristallo di Resonite Incantato⟧, poi uccidi Goggeroc. Torna da Mor'rogal con la notizia e il ⟦Enchanted Resonite Crystal=Cristallo di Resonite Incantato⟧.", "Hai scoperto una minaccia oscura per questa terra, {class}. Il barile di Resonite che hai trovato in quella grotta racchiude un Terrigeno addormentato di nome Goggeroc.\n\nCon i miei poteri sciamanici ho modificato la miscela dei cristalli di Resonite che hai raccolto. Prendi il cristallo di Resonite incantato e sfonda il barile di Resonite che racchiude il Terrigeno.\n\nAl risveglio, Goggeroc sarà indebolito... Uccidilo, {name}!", "Temo che, se non eliminiamo subito questa minaccia, tutta ⟦Stonetalon=Petrartiglio⟧ sarà perduta. La potenza di un Terrigeno non può essere eguagliata in alcun modo. Al risveglio, Goggeroc sarà debole per il lungo sonno: questa è l'occasione che devi sfruttare... va', {name}!", "Porti buone notizie, {class}! Temevo ciò che un Terrigeno avrebbe potuto significare per Kalimdor.\n\nUccidere Goggeroc era un compito che solo un eroe poteva affrontare. Hai fatto bene; tutta ⟦Stonetalon=Petrartiglio⟧ e tutto Kalimdor sono in debito con te, nobile {class}.\n\nAccetta questa ricompensa, tu che sei tra i più onorati.", 0xab18846e, 0xe822594e, 0x79cb0289, 0x6c9c4921, 0x50265ed0, "....." },
  [6523] = { "Proteggi Kaya", "Scorta Kaya Flathoof fino all'⟦Camp Aparaje=Accampamento Aparaje⟧, poi torna da Makaba Flathoof, vicino al margine sud-orientale di ⟦Stonetalon=Petrartiglio⟧.", "Grazie per avermi salvata! Dobbiamo andarcene in fretta, prima che scoprano che sono libera. Ti prego, scortami fino all'⟦Camp Aparaje=Accampamento Aparaje⟧. Da lì so la strada.\n\nMio padre, Makaba Flathoof, sarà disperato di sapere che sono al sicuro.", nil, "Kaya è viva! {name}, devo a te il suo salvataggio.", 0x15129e83, 0xe5af41d4, 0xd4cff830, nil, 0x59df4b81, "...m." },
  [6541] = { "Rapporto a Kadrak", "Fai rapporto a Kadrak, alla torre di guardia nelle ⟦Barrens=Savane⟧ settentrionali.", "Sei mai stat<o/a> a ⟦Ashenvale=Valtetra⟧, a nord? L'Orda ha da poco stabilito un avamposto sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, e ci servono sempre nuove reclute per difendere i nostri nuovi fronti.\n\nSe te la senti, va' da Kadrak nelle ⟦Barrens=Savane⟧ settentrionali, alla torre di guardia. È lui a guidare la campagna di ⟦Ashenvale=Valtetra⟧ e potrà darti altri ordini.", nil, "⟦Ashenvale=Valtetra⟧ è una terra divisa, ma i nostri ultimi sforzi hanno avuto molto successo. Non solo abbiamo un avamposto sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, ma anche un altro poco più a nord di qui, chiamato Troncorotto.", 0x76d74aab, 0x6b18afa9, 0xea704af2, nil, 0x79ee031c, "...m." },
  [6542] = { "Rapporto a Kadrak", "Fai rapporto a Kadrak, alla torre di guardia nelle ⟦Barrens=Savane⟧ settentrionali.", "Sei mai stat<o/a> a ⟦Ashenvale=Valtetra⟧, a nord? L'Orda ha da poco stabilito un avamposto sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, e ci servono sempre nuove reclute per difendere i nostri nuovi fronti.\n\nSe te la senti, va' da Kadrak nelle ⟦Barrens=Savane⟧ settentrionali, alla torre di guardia. È lui a guidare la campagna di ⟦Ashenvale=Valtetra⟧ e potrà darti altri ordini.", nil, "⟦Ashenvale=Valtetra⟧ è una terra divisa, ma i nostri ultimi sforzi hanno avuto molto successo. Non solo abbiamo un avamposto sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, ma anche un altro poco più a nord di qui, chiamato Troncorotto.", 0x76d74aab, 0x6b18afa9, 0xea704af2, nil, 0x79ee031c, "...m." },
  [6543] = { "I rapporti dei ⟦Warsong=Cantaguerra⟧", "Apri il ⟦Bundle of Reports=Fascicolo di Rapporti⟧. Porta i Rapporti dei ⟦Warsong=Cantaguerra⟧ al Warsong Scout, al Warsong Runner e al Warsong Outrider. Riporta gli aggiornamenti che ti daranno a Kadrak, alla torre di guardia settentrionale nelle Savane.", "Di recente ho mandato alcuni esploratori a ⟦Ashenvale=Valtetra⟧ e mi serve un messaggero che porti loro gli ordini e mi riporti un rapporto su ciò che hanno osservato.\n\nLa tua prima tappa dev'essere l'⟦Zoram'gar Outpost=Avamposto di Zoram'gar⟧, lungo la costa a ovest, sulla ⟦Zoram Strand=Spiaggia di Zoram⟧, per trovare il primo messaggero. Devi fermarti anche all'⟦Splintertree Post=Avamposto di Troncorotto⟧, a nord, e lungo la strada a est, vicino ad Azshara. Lì troverai un esploratore e un battistrada.\n\nDai a ciascuno un rapporto e fatti dare un aggiornamento su ciò che hanno scoperto.", "Sbrigati, {name}. Devono ricevere i loro rapporti; è urgente.", "Vedo che sei una persona su cui si può contare. Questi aggiornamenti sono cruciali per i nostri piani di rafforzare la nostra presenza a ⟦Ashenvale=Valtetra⟧. Ora possiamo pianificare la prossima mossa.", 0xf2bef2e2, 0xff13d2f5, 0x7d33a1a0, 0xe0ca1342, 0xd9ec4538, "....." },
  [6545] = { "⟦Warsong Runner Update=Aggiornamenti dal Messaggero dei Cantaguerra⟧", nil, nil, "Quindi sei qui con i miei ordini? È sempre un piacere vedere una nuova recluta piena di entusiasmo e di forte volontà.\n\nFaresti meglio a imparare in fretta, se vuoi tenere il passo qui. La minaccia dei naga cresce, {name}. Da quando sono arrivato ho osservato e respinto diversi attacchi contro questo avamposto.\n\nMa se vuoi dare una mano in questa impresa, parla con uno degli altri qui all'avamposto.", "Bene, il mio rapporto spiegherà tutto questo a Kadrak. Devi riportarglielo il prima possibile.", 0x6770a57c, nil, nil, 0x51947fed, 0x7f206db5, ".mm.." },
  [6548] = { "Vendica il mio villaggio", "Uccidi 8 Grimtotem Ruffian e 6 Grimtotem Mercenary, poi torna da Makaba Flathoof, vicino al margine sud-orientale di ⟦Stonetalon=Petrartiglio⟧.", "Il clan dei ⟦Grimtotem=Totem Truce⟧ ha assaltato il mio villaggio e ha ucciso quasi tutti. Ne ho uccisi quanti ho potuto, ma sono scampato a malapena.\n\n{name}, ora desidero solo che altri di loro muoiano. Li troverai poco più a ovest di qui.", "Li hai già uccisi?", "{name}, ti ringrazio... ma non dimenticherò mai ciò che i ⟦Grimtotem=Totem Truce⟧ hanno fatto al mio villaggio.", 0x7672b786, 0x3188b556, 0x2e43c3b5, 0x8436fd53, 0x3876ab77, "....." },
  [6629] = { "Uccidi Grundig Darkcloud", "Uccidi Grundig Darkcloud e 6 Grimtotem Brute, poi torna da Makaba Flathoof, vicino al margine sud-orientale di ⟦Stonetalon=Petrartiglio⟧.", "{name}, hai fatto un ottimo lavoro contro i ⟦Grimtotem=Totem Truce⟧. Se osi, Grundig Darkcloud e la sua banda personale di bruti sono di gran lunga i peggiori. È stato lui a guidare il brutale attacco al mio villaggio.\n\nLo troverai all'⟦Grimtotem Post=Avamposto dei Totem Truce⟧, poco più avanti lungo il sentiero verso ovest. Uccidilo e te ne sarò grato per sempre.", "Hai ucciso Grundig Darkcloud e la sua banda personale di bruti?", "Grundig Darkcloud è morto! {name}, ti sarò sempre grato per ciò che hai fatto qui oggi.", 0x9168fe63, 0x410c3d4d, 0x726195b3, 0x20857c13, 0xa13011e8, "....." },
  [6661] = { "Retata di ratti degli Abissi", "Cattura 5 Deeprun Rat usando il ⟦Rat Catcher's Flute=Piffero Acchiapparatti⟧. Riporta i ratti da Monty. Non dimenticare di restituire il piffero quando hai finito.", "Avast, marrano. Arrrr... Arrrr, cerchi lavoro? Abbiamo un serio problema di ratti quaggiù, e troppe poche braccia sul ponte di poppa.\n\nChe ne dici? Devi solo prendere questo piffero acchiapparatti e suonare la melodia vicino ai topacci. Ti seguiranno fino ai confini del mondo!\n\nCattura cinque di quelle bestiacce e riportale qui. Ci servono vive.\n\nArrrrr...", "Yarrr... Mozzo, che ci metti tanto?", "Questi andranno benone, compare. A mi' fratello servono ancora vivi e scalcianti, sennò vanno a male... E tu non vuoi assaggiare uno spiedino di ratto andato a male.", 0x058b4f5c, 0xc9e92c7d, 0x5a7d2f9f, 0x43339737, 0xa19d5900, "....." },
  [6662] = { "Mi' fratello, Nipsy", "Porta la ⟦Carton of Mystery Meat=Cassa di Carne Misteriosa⟧ a Nipsy, alla stazione del ⟦Deeprun Tram=Tram degli Abissi⟧ di ⟦Stormwind=Roccavento⟧.", "Mi' fratello, Nipsy, gestisce un'attività di spiedini di ratto dall'altra parte del tram degli Abissi. Devi portargli questa cassa di ratti prima che vadano a male. Muoviti!\n\nSei già salit<o/a> su un tram, eh? È facile. Monta a bordo quando arriva e goditi il viaggio. E tieni braccia e gambe dentro durante la corsa, se non vuoi ritrovarti con una gamba di legno a vita.", "<Nipsy infila l'indice in uno dei buchi per l'aria della cassa.>\n\nVivi e vegeti... e giusto in tempo!", "Povero Monty. Dall'incidente di Gnomeregan non è più lo stesso. Quel ragazzo non ha mai visto un oceano in vita sua, figurarsi fare il pirata.\n\n<Nipsy sospira.>\n\nAlmeno continua a mandarmi un bel flusso di bestiole che si dimenano.", 0xfb9ecfec, 0x87d7d034, 0xb75e7e9d, 0x3088e5a6, 0x9f0f0959, "....." },
  [6721] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è il momento, {class}.", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0xca92f25f, "...m." },
  [6722] = { "La via del cacciatore", "Parla con Dazalar a Dolanaar.", "Salve, giovane <cacciatore/cacciatrice>. Mi sembri abbastanza abile da gestire una bestia e addestrarla come tua compagna.\n\nDevi andare da Dazalar a Dolanaar. Può avviarti sulla strada per ottenere un famiglio tutto tuo.", nil, "Sì, è il momento di addestrarti...", 0xe59cef47, 0xacb77771, 0x57c4b6af, nil, 0x6d03693e, "...m." },
  [6961] = { "Great-father Winter è arrivato!", "Parla con Greatfather Winter: si trova vicino all'area dei venditori di Smokywood Pastures, a Orgrimmar.", "Buon Winter Veil, amico! Non dimenticare di salutare Greatfather Winter! Se quest'anno sei stat<o/a> buon<o/a>, riceverai doni meravigliosi il giorno del Feast of Winter Veil. Non dimenticare di dirgli cosa speri di ricevere quest'anno!\n\nE non dimenticare di fare scorta di dolcetti da regalare a chi è stato buono quest'anno. Abbiamo un'ampia scelta. Dalla nostra fattoria alla tua tavola: è la bontà genuina di Smokywood Pastures!", nil, "Oh oh oh, salve. Sono Greatfather Winter e, per gentile concessione della brava gente di Smokywood Pastures... \"Dalla nostra fattoria alla tua tavola: è la bontà genuina di Smokywood Pastures\"... ti auguro un fantastico Feast of Winter Veil.\n\nSe quest'anno sei stat<o/a> buon<o/a>, forse riceverai dei dolcetti da Smokywood Pastures come regalo per il Feast of Winter Veil. Urrà.", 0x9a9ce503, 0x591cc909, 0xba4aa7ab, nil, 0x296b27e3, "...m." },
  [6962] = { "Dolcetti per Great-father Winter", "Porta 5 Gingerbread Cookie e un ⟦Ice Cold Milk=Latte Ghiacciato⟧ a Greatfather Winter, a Orgrimmar.", "Ehi, puoi fare un favore a Greatfather Winter, ehm, <bimbo/bimba>?\n\nNon per parlare di me in terza persona senza motivo, ma Greatfather Winter è all'opera da tutto il giorno e un dolcetto gli farebbe proprio comodo. Qualche biscotto di pan di zenzero e del latte ghiacciato per mandarli giù sarebbero proprio l'ideale. Credi di poter essere un amico per il Greatfather e andarmene a prendere un po'?", "Tutto questo parlare di dolcetti mi ha fatto venire voglia di mangiarne qualcuno. Mmmm... biscotti di pan di zenzero e latte...", "Sei proprio un bell'aiutante per il vecchio Greatfather Winter, {name}. Buon Feast of Winter Veil.\n\nEcco un pensierino... sai, per il disturbo.", 0xf3a28acd, 0xf01a51da, 0xd3822e00, 0x11c73f24, 0x004980cd, ".....", nil, nil, 0xcc6e16c8, nil, nil },
})
